"""Distinguish archive documents, versions, relationship quarters and snapshots."""
import pathlib,sqlite3,json,collections
P=pathlib.Path(__file__).resolve().parent

def run():
 d=sqlite3.connect(P/'house-filings.sqlite');out={'population':'All members of the four 2025 quarterly archives plus the 2025 registrations archive listed by the official House download index, acquired 7 October 2026. These are report-year archive selections, not a received-during-2025 census.','records':d.execute('select count(*) from filings').fetchone()[0],'report_years':dict(d.execute('select year,count(*) from filings group by year')),'signed_date_range':list(d.execute('select min(signed),max(signed) from filings').fetchone()),'signed_dates_are_not_filing_received_dates':True,'duplicate_document_ids':0,'byte_identical_xml_duplicates':d.execute('select count(*)-count(distinct sha256) from filings').fetchone()[0],'quarterly_document_records':d.execute("select count(*) from filings where quarter!='registration'").fetchone()[0],'relationship_quarters':d.execute("select count(*) from (select house_id,quarter from filings where quarter!='registration' group by house_id,quarter)").fetchone()[0],'registration_and_amendment_records':d.execute("select count(*) from filings where quarter='registration'").fetchone()[0],'distinct_registration_relationships':d.execute("select count(distinct house_id) from filings where quarter='registration'").fetchone()[0],'archives':[dict(zip(['quarter','records','relationships','earliest_signed','latest_signed'],r)) for r in d.execute('select quarter,count(*),count(distinct house_id),min(signed),max(signed) from filings group by quarter')],'report_types':dict(d.execute('select report_type,count(*) from filings group by report_type')),'interpretation':'Originals, amendments, termination reports and amended terminations are separate document records. For provisional annual totals only one signed-date/document-ID version per relationship quarter is used. Source role matching retains all versions and must not be summed as spending. The same relationship legitimately occurs in multiple quarters and in registration files. All thirteen initial major totals were separately verified by API posting chronology and original HTML. House snapshot is not independently proven identical to API population.'}
 out['additional_quarter_versions']=out['quarterly_document_records']-out['relationship_quarters']
 (P/'archive-scope.json').write_text(json.dumps(out,indent=2));print(out)
if __name__=='__main__':run()
